-- BOWMASTERS
-- Do not edit this file. Any change breaks the decoder.
local _wmmkis = 169
local _mlygry = 27
local _wpbsci = 51
local _unewuj = ""

local _effmig = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _iryytb(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _taptrt(d)
	d = d:gsub("[^" .. _effmig .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_effmig:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _armizh = _taptrt(_unewuj)
local _tjxzhi = { _wmmkis, _mlygry, _wpbsci }
local _hkiifk = {}
for i = 1, #_armizh do
	_hkiifk[i] = string.char(_iryytb(_armizh:byte(i), _tjxzhi[(i - 1) % 3 + 1]))
end

local _rjddln = load or loadstring
local _rzwgwk, _aaayca = _rjddln(table.concat(_hkiifk), "=w")
if not _rzwgwk then
	gg.alert("Corrupted file: " .. tostring(_aaayca))
	os.exit()
end
_rzwgwk()
